insert into public.agent_questions(chapter_id,field_path,prompt,position,required,config)
select c.id, v.agent_key||'.'||v.chapter_key, v.prompt, 1, true, jsonb_build_object('source','fas-build-specs')
from (values
('anchor','authority','What do people already trust you to help them do?'),('anchor','arena','Who most needs that result right now?'),('anchor','evidence','What specific evidence can you legitimately use?'),('anchor','position','What do you believe the market gets wrong?'),('anchor','boundaries','What will you not promise, claim, or deliver?'),('anchor','activation','What visible action will demonstrate this position in the next 30 days?'),
('extract','context','What do people already come to you for help with?'),('extract','diagnostic','Where is the business today in revenue, audience, offer, and sales process?'),('extract','origin','What problem did you first have to solve for yourself?'),('extract','timeline','Which jobs, clients, failures, and breakthroughs shaped how you work?'),('extract','method','Teach me through one recent transformation from the first action onward.'),('extract','proof','What evidence supports each result you have described?'),('extract','point_of_view','What does your market commonly get wrong?'),('extract','boundaries','What expertise, claims, or stories must remain outside the public artifact?'),('extract','synthesis','What feels missing or inaccurate in this summary?'),
('radar','market','Which group can you credibly reach and help now?'),('radar','evidence','What buyer evidence do you already have from calls, messages, forms, or behavior?'),('radar','current_state','What is visibly happening before they seek help?'),('radar','desired_state','What practical and emotional change are they seeking?'),('radar','triggers','What event makes solving this urgent?'),('radar','objections','What do they say when they hesitate?'),('radar','language','What exact words have real buyers used?'),('radar','priority','Which segment scores highest for access, urgency, ability to pay, credibility, fit, and evidence?'),('radar','approval','What must change before you approve this?'),
('forge','strategy','What buyer, outcome, method, category, and tone must the name express?'),('forge','territories','Which three distinct naming directions fit the strategy?'),('forge','candidates','Which names feel clear, memorable, relevant, and pronounceable?'),('forge','shortlist','How would you rank the strongest nine candidates?'),('forge','stress_test','Say each finalist in a referral, webinar, product title, and social bio.'),('forge','selection','Which three finalists would you carry forward, and why?'),('forge','screening','Which domain, handle, search, and trademark checks have you completed?'),('forge','identity','How should the selected identity sound and look in practice?'),
('architect','transformation','What start state and observable end state should the program create?'),('architect','milestones','What three to five changes must happen in sequence?'),('architect','phases','What are the chapters or pillars of the method?'),('architect','modules','What outcome, prerequisite, action, and completion proof belongs to each module?'),('architect','lessons','What does the client need to learn at this exact point?'),('architect','implementation','Which worksheets, assessments, feedback, and coaching touchpoints are required?'),('architect','overload','What can move to support, bonus, or a future version?'),('architect','delivery','Do client effort and coach capacity fit the promised model?'),('architect','approval','What must change before you approve this curriculum?'),
('voice','input_gate','Which approved expert, buyer, brand, program, proof, and boundary facts are ready?'),('voice','content_job','What one asset and channel are we writing first?'),('voice','context','What does the reader already know and feel when they encounter this asset?'),('voice','gap_check','Which proof, offer term, or call to action is still missing?'),('voice','message_brief','Who is the one reader, what problem matters now, and what action should they take?'),('voice','draft','Which section should we draft and approve first?'),('voice','checks','Which claim needs stronger evidence or a clearer boundary?'),('voice','approval','What must change before this copy is approved?'),
('launch','launch_type','Is this a beta, live launch, evergreen activation, or another rollout?'),('launch','dates','Which launch, sales-window, delivery, and blackout dates are confirmed?'),('launch','prerequisites','Which offer, checkout, copy, audience, proof, tech, and fulfillment pieces already exist?'),('launch','backward_plan','What must be true immediately before delivery begins?'),('launch','owners','Who owns each launch-critical task?'),('launch','channels','Which channels can the team actually execute?'),('launch','calendar','Which weekly milestones need daily actions?'),('launch','sales','How will leads, conversations, calls, offers, sales, revenue, and follow-up be recorded?'),('launch','readiness','Which blocked task puts the launch at risk?'),('launch','review','What changed, what worked, and what belongs in the next cycle?')
) as v(agent_key,chapter_key,prompt)
join public.agent_chapters c on c.agent_key=v.agent_key and c.key=v.chapter_key;
commit;

